def reopen_files(self):
    if self.cfg.capture_output and self.cfg.errorlog != "-":
        for stream in sys.stdout, sys.stderr:
            stream.flush()

        with self.lock:
            if self.logfile is not None:
                self.logfile.close()
            self.logfile = open(self.cfg.errorlog, 'a+')
            os.dup2(self.logfile.fileno(), sys.stdout.fileno())
            os.dup2(self.logfile.fileno(), sys.stderr.fileno())

    for log in loggers():
        for handler in log.handlers:
            if isinstance(handler, logging.FileHandler):
                handler.acquire()
                try:
                    if handler.stream:
                        handler.close()
                        handler.stream = handler._open()
                finally:
                    handler.release()

def close_on_exec(self):
    for log in loggers():
        for handler in log.handlers:
            if isinstance(handler, logging.FileHandler):
                handler.acquire()
                try:
                    if handler.stream:
                        util.close_on_exec(handler.stream.fileno())
                finally:
                    handler.release()

def has_fileno(obj):
    if not hasattr(obj, "fileno"):
        return False

    # check BytesIO case and maybe others
    try:
        obj.fileno()
    except (AttributeError, IOError, io.UnsupportedOperation):
        return False

    return True

def notify(self):
    self.spinner = (self.spinner + 1) % 2
    os.fchmod(self._tmp.fileno(), self.spinner)

def __init__(self, atoms):
    dict.__init__(self)
    for key, value in atoms.items():
        if isinstance(value, str):
            self[key] = value.replace('"', '\\"')
        else:
            self[key] = value

def __init__(self, addr, conf, log, fd=None):
    if fd is None:
        try:
            st = os.stat(addr)
        except OSError as e:
            if e.args[0] != errno.ENOENT:
                raise
        else:
            if stat.S_ISSOCK(st.st_mode):
                os.remove(addr)
            else:
                raise ValueError("%r is not a socket" % addr)
    super().__init__(addr, conf, log, fd=fd)

def __init__(self, cfg):
    Logger.__init__(self, cfg)
    self.prefix = sub(r"^(.+[^.]+)\.*$", "\\g<1>.", cfg.statsd_prefix)

    if isinstance(cfg.statsd_host, str):
        address_family = socket.AF_UNIX
    else:
        address_family = socket.AF_INET

    try:
        self.sock = socket.socket(address_family, socket.SOCK_DGRAM)
        self.sock.connect(cfg.statsd_host)
    except Exception:
        self.sock = None

    self.dogstatsd_tags = cfg.dogstatsd_tags

