def __repr__(self):
    return "<%s.%s object at %x with value %r>" % (
        self.__class__.__module__,
        self.__class__.__name__,
        id(self),
        self.value,
    )

def warn(msg):
    print("!!!", file=sys.stderr)

    lines = msg.splitlines()
    for i, line in enumerate(lines):
        if i == 0:
            line = "WARNING: %s" % line
        print("!!! %s" % line, file=sys.stderr)

    print("!!!\n", file=sys.stderr)
    sys.stderr.flush()

def __next__(self):
    # Stop if HTTP dictates a stop.
    if self.mesg and self.mesg.should_close():
        raise StopIteration()

    # Discard any unread body of the previous message
    if self.mesg:
        data = self.mesg.body.read(8192)
        while data:
            data = self.mesg.body.read(8192)

    # Parse the next request
    self.req_count += 1
    self.mesg = self.mesg_class(self.cfg, self.unreader, self.source_addr, self.req_count)
    if not self.mesg:
        raise StopIteration()
    return self.mesg

def __next__(self):
    ret = self.readline()
    if not ret:
        raise StopIteration()
    return ret

def getsize(self, size):
    if size is None:
        return sys.maxsize
    elif not isinstance(size, int):
        raise TypeError("size must be an integral type")
    elif size < 0:
        return sys.maxsize
    return size

def readline(self, size=None):
    size = self.getsize(size)
    if size == 0:
        return b""

    data = self.buf.getvalue()
    self.buf = io.BytesIO()

    ret = []
    while 1:
        idx = data.find(b"\n", 0, size)
        idx = idx + 1 if idx >= 0 else size if len(data) >= size else 0
        if idx:
            ret.append(data[:idx])
            self.buf.write(data[idx:])
            break

        ret.append(data)
        size -= len(data)
        data = self.reader.read(min(1024, size))
        if not data:
            break

    return b"".join(ret)

def chunk(self):
    if not self.iter:
        return b""
    try:
        return next(self.iter)
    except StopIteration:
        self.iter = None
        return b""

def parse_syslog_address(addr):

    # unix domain socket type depends on backend
    # SysLogHandler will try both when given None
    if addr.startswith("unix://"):
        sock_type = None

        # set socket type only if explicitly requested
        parts = addr.split("#", 1)
        if len(parts) == 2:
            addr = parts[0]
            if parts[1] == "dgram":
                sock_type = socket.SOCK_DGRAM

        return (sock_type, addr.split("unix://")[1])

    if addr.startswith("udp://"):
        addr = addr.split("udp://")[1]
        socktype = socket.SOCK_DGRAM
    elif addr.startswith("tcp://"):
        addr = addr.split("tcp://")[1]
        socktype = socket.SOCK_STREAM
    else:
        raise RuntimeError("invalid syslog address")

    if '[' in addr and ']' in addr:
        host = addr.split(']')[0][1:].lower()
    elif ':' in addr:
        host = addr.split(':')[0].lower()
    elif addr == "":
        host = "localhost"
    else:
        host = addr.lower()

    addr = addr.split(']')[-1]
    if ":" in addr:
        port = addr.split(':', 1)[1]
        if not port.isdigit():
            raise RuntimeError("%r is not a valid port number." % port)
        port = int(port)
    else:
        port = 514

    return (socktype, (host, port))

def setup(self, cfg):
    self.loglevel = self.LOG_LEVELS.get(cfg.loglevel.lower(), logging.INFO)
    self.error_log.setLevel(self.loglevel)
    self.access_log.setLevel(logging.INFO)

    # set gunicorn.error handler
    if self.cfg.capture_output and cfg.errorlog != "-":
        for stream in sys.stdout, sys.stderr:
            stream.flush()

        self.logfile = open(cfg.errorlog, 'a+')
        os.dup2(self.logfile.fileno(), sys.stdout.fileno())
        os.dup2(self.logfile.fileno(), sys.stderr.fileno())

    self._set_handler(self.error_log, cfg.errorlog,
                      logging.Formatter(self.error_fmt, self.datefmt))

    # set gunicorn.access handler
    if cfg.accesslog is not None:
        self._set_handler(
            self.access_log, cfg.accesslog,
            fmt=logging.Formatter(self.access_fmt), stream=sys.stdout
        )

    # set syslog handler
    if cfg.syslog:
        self._set_syslog_handler(
            self.error_log, cfg, self.syslog_fmt, "error"
        )
        if not cfg.disable_redirect_access_to_syslog:
            self._set_syslog_handler(
                self.access_log, cfg, self.syslog_fmt, "access"
            )

    if cfg.logconfig_dict:
        config = CONFIG_DEFAULTS.copy()
        config.update(cfg.logconfig_dict)
        try:
            dictConfig(config)
        except (
                AttributeError,
                ImportError,
                ValueError,
                TypeError
        ) as exc:
            raise RuntimeError(str(exc))
    elif cfg.logconfig_json:
        config = CONFIG_DEFAULTS.copy()
        if os.path.exists(cfg.logconfig_json):
            try:
                config_json = json.load(open(cfg.logconfig_json))
                config.update(config_json)
                dictConfig(config)
            except (
                json.JSONDecodeError,
                AttributeError,
                ImportError,
                ValueError,
                TypeError
            ) as exc:
                raise RuntimeError(str(exc))
    elif cfg.logconfig:
        if os.path.exists(cfg.logconfig):
            defaults = CONFIG_DEFAULTS.copy()
            defaults['__file__'] = cfg.logconfig
            defaults['here'] = os.path.dirname(cfg.logconfig)
            fileConfig(cfg.logconfig, defaults=defaults,
                       disable_existing_loggers=False)
        else:
            msg = "Error: log config '%s' not found"
            raise RuntimeError(msg % cfg.logconfig)

def _get_gunicorn_handler(self, log):
    for h in log.handlers:
        if getattr(h, "_gunicorn", False):
            return h

def _set_handler(self, log, output, fmt, stream=None):
    # remove previous gunicorn log handler
    h = self._get_gunicorn_handler(log)
    if h:
        log.handlers.remove(h)

    if output is not None:
        if output == "-":
            h = logging.StreamHandler(stream)
        else:
            util.check_is_writable(output)
            h = logging.FileHandler(output)
            # make sure the user can reopen the file
            try:
                os.chown(h.baseFilename, self.cfg.user, self.cfg.group)
            except OSError:
                # it's probably OK there, we assume the user has given
                # /dev/null as a parameter.
                pass

        h.setFormatter(fmt)
        h._gunicorn = True
        log.addHandler(h)

def log(self, lvl, msg, *args, **kwargs):
