        # Force the connection closed until someone shows
        # a buffering proxy that supports Keep-Alive to
        # the backend.
        resp.force_close()
        self.nr += 1
        if self.nr >= self.max_requests:
            self.log.info("Autorestarting worker after current request.")
            self.alive = False
        respiter = self.wsgi(environ, resp.start_response)
        try:
            if isinstance(respiter, environ['wsgi.file_wrapper']):
                resp.write_file(respiter)
            else:
                for item in respiter:
                    resp.write(item)
            resp.close()
        finally:
            request_time = datetime.now() - request_start
            self.log.access(resp, req, environ, request_time)
            if hasattr(respiter, "close"):
                respiter.close()
    except EnvironmentError:
        # pass to next try-except level
        util.reraise(*sys.exc_info())
    except Exception:
        if resp and resp.headers_sent:
            # If the requests have already been sent, we should close the
            # connection to indicate the error.
            self.log.exception("Error handling request")
            try:
                client.shutdown(socket.SHUT_RDWR)
                client.close()
            except EnvironmentError:
                pass
            raise StopIteration()
        raise
    finally:
        try:
            self.cfg.post_request(self, req, environ, resp)
        except Exception:
            self.log.exception("Exception in post_request hook")

def handle_request(self, listener_name, req, sock, addr):
    try:
        super().handle_request(listener_name, req, sock, addr)
    except gevent.GreenletExit:
        pass
    except SystemExit:
        pass

def handle_request(self, req, conn):
    environ = {}
    resp = None
    try:
        self.cfg.pre_request(self, req)
        request_start = datetime.now()
        resp, environ = wsgi.create(req, conn.sock, conn.client,
                                    conn.server, self.cfg)
        environ["wsgi.multithread"] = True
        self.nr += 1
        if self.nr >= self.max_requests:
            if self.alive:
                self.log.info("Autorestarting worker after current request.")
                self.alive = False
            resp.force_close()

        if not self.alive or not self.cfg.keepalive:
            resp.force_close()
        elif len(self._keep) >= self.max_keepalived:
            resp.force_close()

        respiter = self.wsgi(environ, resp.start_response)
        try:
            if isinstance(respiter, environ['wsgi.file_wrapper']):
                resp.write_file(respiter)
            else:
                for item in respiter:
                    resp.write(item)

            resp.close()
        finally:
            request_time = datetime.now() - request_start
            self.log.access(resp, req, environ, request_time)
            if hasattr(respiter, "close"):
                respiter.close()

        if resp.should_close():
            self.log.debug("Closing connection.")
            return False
    except EnvironmentError:
        # pass to next try-except level
        util.reraise(*sys.exc_info())
    except Exception:
        if resp and resp.headers_sent:
            # If the requests have already been sent, we should close the
            # connection to indicate the error.
            self.log.exception("Error handling request")
            try:
                conn.sock.shutdown(socket.SHUT_RDWR)
                conn.sock.close()
            except EnvironmentError:
                pass
            raise StopIteration()
        raise
    finally:
        try:
            self.cfg.post_request(self, req, environ, resp)
        except Exception:
            self.log.exception("Exception in post_request hook")

    return True

def __str__(self):
    if self.conf.is_ssl:
        scheme = "https"
    else:
        scheme = "http"

    addr = self.sock.getsockname()
    return "%s://%s:%d" % (scheme, addr[0], addr[1])

def __str__(self):
    (host, port, _, _) = self.sock.getsockname()
    return "http://[%s]:%d" % (host, port)

def __str__(self):
    lines = []
    kmax = max(len(k) for k in self.settings)
    for k in sorted(self.settings):
        v = self.settings[k].value
        if callable(v):
            v = "<{}()>".format(v.__qualname__)
        lines.append("{k:{kmax}} = {v}".format(k=k, v=v, kmax=kmax))
    return "\n".join(lines)

def set_options(self, sock, bound=False):
    sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    if (self.conf.reuse_port
            and hasattr(socket, 'SO_REUSEPORT')):  # pragma: no cover
        try:
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
        except socket.error as err:
            if err.errno not in (errno.ENOPROTOOPT, errno.EINVAL):
                raise
    if not bound:
        self.bind(sock)
    sock.setblocking(0)

    # make sure that the socket can be inherited
    if hasattr(sock, "set_inheritable"):
        sock.set_inheritable(True)

    sock.listen(self.conf.backlog)
    return sock

def set_options(self, sock, bound=False):
    sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
    return super().set_options(sock, bound=bound)

def _sock_type(addr):
    if isinstance(addr, tuple):
        if util.is_ipv6(addr[0]):
            sock_type = TCP6Socket
        else:
            sock_type = TCPSocket
    elif isinstance(addr, (str, bytes)):
        sock_type = UnixSocket
    else:
        raise TypeError("Unable to create socket from: %r" % addr)
    return sock_type

def close_sockets(listeners, unlink=True):
    for sock in listeners:
        sock_name = sock.getsockname()
        sock.close()
        if unlink and _sock_type(sock_name) is UnixSocket:
            os.unlink(sock_name)

def close(sock):
    try:
        sock.close()
    except socket.error:
        pass

def write_chunk(sock, data):
    if isinstance(data, str):
        data = data.encode('utf-8')
    chunk_size = "%X\r\n" % len(data)
    chunk = b"".join([chunk_size.encode('utf-8'), data, b"\r\n"])
    sock.sendall(chunk)

def write(sock, data, chunked=False):
    if chunked:
        return write_chunk(sock, data)
    sock.sendall(data)

def write_nonblock(sock, data, chunked=False):
    timeout = sock.gettimeout()
    if timeout != 0.0:
        try:
            sock.setblocking(0)
            return write(sock, data, chunked)
        finally:
            sock.setblocking(1)
    else:
        return write(sock, data, chunked)

def close(self):
    if self.sock is None:
        return

    try:
        self.sock.close()
    except socket.error as e:
        self.log.info("Error while closing socket %s", str(e))

    self.sock = None

def should_close(self):
    for (h, v) in self.headers:
        if h == "CONNECTION":
            v = v.lower().strip()
            if v == "close":
                return True
            elif v == "keep-alive":
                return False
            break
    return self.version <= (1, 0)

def handle_request(self):
    self.nr += 1
    if self.alive and self.nr >= self.max_requests:
        self.log.info("Autorestarting worker after current request.")
        self.alive = False

def finish(other):
    self.handle_request()
    old_connection_finish(other)

def on_close(instance, server_conn):
    self.handle_request()
    super(_HTTPServer, instance).on_close(server_conn)

def make_settings(ignore=None):
    settings = {}
    ignore = ignore or ()
    for s in KNOWN_SETTINGS:
        setting = s()
        if setting.name in ignore:
            continue
        settings[setting.name] = setting.copy()
    return settings

def get_cmd_args_from_env(self):
    if 'GUNICORN_CMD_ARGS' in self.env_orig:
        return shlex.split(self.env_orig['GUNICORN_CMD_ARGS'])
    return []

def paste_global_conf(self):
    raw_global_conf = self.settings['raw_paste_global_conf'].get()
    if raw_global_conf is None:
        return None

    global_conf = {}
    for e in raw_global_conf:
        s = util.bytes_to_str(e)
        try:
            k, v = re.split(r'(?<!\\)=', s, 1)
        except ValueError:
            raise RuntimeError("environment setting %r invalid" % s)
        k = k.replace('\\=', '=')
        v = v.replace('\\=', '=')
        global_conf[k] = v

    return global_conf

def get_default_config_file():
    config_path = os.path.join(os.path.abspath(os.getcwd()),
                               'gunicorn.conf.py')
    if os.path.exists(config_path):
        return config_path
    return None

def load_default_config(self):
    # init configuration
    self.cfg = Config(self.usage, prog=self.prog)

def get_config_from_filename(self, filename):

    if not os.path.exists(filename):
        raise RuntimeError("%r doesn't exist" % filename)

    ext = os.path.splitext(filename)[1]

    try:
        module_name = '__config__'
        if ext in [".py", ".pyc"]:
            spec = importlib.util.spec_from_file_location(module_name, filename)
        else:
            msg = "configuration file should have a valid Python extension.\n"
            util.warn(msg)
            loader_ = importlib.machinery.SourceFileLoader(module_name, filename)
            spec = importlib.util.spec_from_file_location(module_name, filename, loader=loader_)
        mod = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = mod
        spec.loader.exec_module(mod)
    except Exception:
        print("Failed to read config file: %s" % filename, file=sys.stderr)
        traceback.print_exc()
        sys.stderr.flush()
        sys.exit(1)

    return vars(mod)

def load_config_from_module_name_or_filename(self, location):
    """
    Loads the configuration file: the file is a python file, otherwise raise an RuntimeError
    Exception or stop the process if the configuration file contains a syntax error.
    """

    if location.startswith("python:"):
        module_name = location[len("python:"):]
        cfg = self.get_config_from_module_name(module_name)
    else:
        if location.startswith("file:"):
            filename = location[len("file:"):]
        else:
            filename = location
        cfg = self.get_config_from_filename(filename)

    for k, v in cfg.items():
        # Ignore unknown names
        if k not in self.cfg.settings:
            continue
        try:
            self.cfg.set(k.lower(), v)
        except Exception:
            print("Invalid value for %s: %s\n" % (k, v), file=sys.stderr)
            sys.stderr.flush()
            raise

    return cfg

def load_config(self):
    # parse console args
    parser = self.cfg.parser()
    args = parser.parse_args()

    # optional settings from apps
    cfg = self.init(parser, args, args.args)

    # set up import paths and follow symlinks
    self.chdir()

    # Load up the any app specific configuration
    if cfg:
        for k, v in cfg.items():
            self.cfg.set(k.lower(), v)

    env_args = parser.parse_args(self.cfg.get_cmd_args_from_env())

    if args.config:
        self.load_config_from_file(args.config)
    elif env_args.config:
        self.load_config_from_file(env_args.config)
    else:
        default_config = get_default_config_file()
        if default_config is not None:
            self.load_config_from_file(default_config)

    # Load up environment configuration
    for k, v in vars(env_args).items():
        if v is None:
            continue
        if k == "args":
            continue
        self.cfg.set(k.lower(), v)

    # Lastly, update the configuration with any command line settings.
    for k, v in vars(args).items():
        if v is None:
            continue
        if k == "args":
            continue
        self.cfg.set(k.lower(), v)

    # current directory might be changed by the config now
    # set up import paths and follow symlinks
    self.chdir()

def load_config(self):
    super().load_config()

    if self.app_uri is None:
        if self.cfg.wsgi_app is not None:
            self.app_uri = self.cfg.wsgi_app
        else:
            raise ConfigError("No application module specified.")

def load_config(self):
