def validate_reload_engine(val):
    if val not in reloader_engines:
        raise ConfigError("Invalid reload_engine: %r" % val)

    return val

def murder_workers(self):
    """\
    Kill unused/idle workers
    """
    if not self.timeout:
        return
    workers = list(self.WORKERS.items())
    for (pid, worker) in workers:
        try:
            if time.time() - worker.tmp.last_update() <= self.timeout:
                continue
        except (OSError, ValueError):
            continue

        if not worker.aborted:
            self.log.critical("WORKER TIMEOUT (pid:%s)", pid)
            worker.aborted = True
            self.kill_worker(pid, signal.SIGABRT)
        else:
            self.kill_worker(pid, signal.SIGKILL)

def reap_workers(self):
    """\
    Reap workers to avoid zombie processes
    """
    try:
        while True:
            wpid, status = os.waitpid(-1, os.WNOHANG)
            if not wpid:
                break
            if self.reexec_pid == wpid:
                self.reexec_pid = 0
            else:
                # A worker was terminated. If the termination reason was
                # that it could not boot, we'll shut it down to avoid
                # infinite start/stop cycles.
                exitcode = status >> 8
                if exitcode != 0:
                    self.log.error('Worker (pid:%s) exited with code %s', wpid, exitcode)
                if exitcode == self.WORKER_BOOT_ERROR:
                    reason = "Worker failed to boot."
                    raise HaltServer(reason, self.WORKER_BOOT_ERROR)
                if exitcode == self.APP_LOAD_ERROR:
                    reason = "App failed to load."
                    raise HaltServer(reason, self.APP_LOAD_ERROR)

                if exitcode > 0:
                    # If the exit code of the worker is greater than 0,
                    # let the user know.
                    self.log.error("Worker (pid:%s) exited with code %s.",
                                   wpid, exitcode)
                elif status > 0:
                    # If the exit code of the worker is 0 and the status
                    # is greater than 0, then it was most likely killed
                    # via a signal.
                    try:
                        sig_name = signal.Signals(status).name
                    except ValueError:
                        sig_name = "code {}".format(status)
                    msg = "Worker (pid:{}) was sent {}!".format(
                        wpid, sig_name)

                    # Additional hint for SIGKILL
                    if status == signal.SIGKILL:
                        msg += " Perhaps out of memory?"
                    self.log.error(msg)

                worker = self.WORKERS.pop(wpid, None)
                if not worker:
                    continue
                worker.tmp.close()
                self.cfg.child_exit(self, worker)
    except OSError as e:
        if e.errno != errno.ECHILD:
            raise

def kill_worker(self, pid, sig):
    """\
    Kill a worker

    :attr pid: int, worker pid
    :attr sig: `signal.SIG*` value
     """
    try:
        os.kill(pid, sig)
    except OSError as e:
        if e.errno == errno.ESRCH:
            try:
                worker = self.WORKERS.pop(pid)
                worker.tmp.close()
                self.cfg.worker_exit(self, worker)
                return
            except (KeyError, OSError):
                return
        raise

def run(self):
    # if no timeout is given the worker will never wait and will
    # use the CPU for nothing. This minimal timeout prevent it.
    timeout = self.timeout or 0.5

    # self.socket appears to lose its blocking status after
    # we fork in the arbiter. Reset it here.
    for s in self.sockets:
        s.setblocking(0)

    if len(self.sockets) > 1:
        self.run_for_multiple(timeout)
    else:
        self.run_for_one(timeout)

def validate(self):
    """ Validate pidfile and make it stale if needed"""
    if not self.fname:
        return
    try:
        with open(self.fname, "r") as f:
            try:
                wpid = int(f.read())
            except ValueError:
                return

            try:
                os.kill(wpid, 0)
                return wpid
            except OSError as e:
                if e.args[0] == errno.EPERM:
                    return wpid
                if e.args[0] == errno.ESRCH:
                    return
                raise
    except IOError as e:
        if e.args[0] == errno.ENOENT:
            return
        raise

def set_non_blocking(fd):
