def split_request_uri(uri):
    if uri.startswith("//"):
        # When the path starts with //, urlsplit considers it as a
        # relative uri while the RFC says we should consider it as abs_path
        # http://www.w3.org/Protocols/rfc2616/rfc2616-sec5.html#sec5.1.2
        # We use temporary dot prefix to workaround this behaviour
        parts = urllib.parse.urlsplit("." + uri)
        return parts._replace(path=parts.path[1:])

    return urllib.parse.urlsplit(uri)

def bytes_to_str(b):
    if isinstance(b, str):
        return b
    return str(b, 'latin1')

def read(self, size):
    if not isinstance(size, int):
        raise TypeError("size must be an integer type")
    if size < 0:
        raise ValueError("Size must be positive.")
    if size == 0:
        return b""

    if self.parser:
        while self.buf.tell() < size:
            try:
                self.buf.write(next(self.parser))
            except StopIteration:
                self.parser = None
                break

    data = self.buf.getvalue()
    ret, rest = data[:size], data[size:]
    self.buf = io.BytesIO()
    self.buf.write(rest)
    return ret

def parse_chunked(self, unreader):
    (size, rest) = self.parse_chunk_size(unreader)
    while size > 0:
        while size > len(rest):
            size -= len(rest)
            yield rest
            rest = unreader.read()
            if not rest:
                raise NoMoreData()
        yield rest[:size]
        # Remove \r\n after chunk
        rest = rest[size:]
        while len(rest) < 2:
            rest += unreader.read()
        if rest[:2] != b'\r\n':
            raise ChunkMissingTerminator(rest[:2])
        (size, rest) = self.parse_chunk_size(unreader, data=rest[2:])

def parse_chunk_size(self, unreader, data=None):
    buf = io.BytesIO()
    if data is not None:
        buf.write(data)

    idx = buf.getvalue().find(b"\r\n")
    while idx < 0:
        self.get_data(unreader, buf)
        idx = buf.getvalue().find(b"\r\n")

    data = buf.getvalue()
    line, rest_chunk = data[:idx], data[idx + 2:]

    chunk_size = line.split(b";", 1)[0].strip()
    try:
        chunk_size = int(chunk_size, 16)
    except ValueError:
        raise InvalidChunkSize(chunk_size)

    if chunk_size == 0:
        try:
            self.parse_trailers(unreader, rest_chunk)
        except NoMoreData:
            pass
        return (0, None)
    return (chunk_size, rest_chunk)

def get_data(self, unreader, buf):
    data = unreader.read()
    if not data:
        raise NoMoreData()
    buf.write(data)

def read(self, size):
    if not isinstance(size, int):
        raise TypeError("size must be an integral type")

    size = min(self.length, size)
    if size < 0:
        raise ValueError("Size must be positive.")
    if size == 0:
        return b""

    buf = io.BytesIO()
    data = self.unreader.read()
    while data:
        buf.write(data)
        if buf.tell() >= size:
            break
        data = self.unreader.read()

    buf = buf.getvalue()
    ret, rest = buf[:size], buf[size:]
    self.unreader.unread(rest)
    self.length -= size
    return ret

def read(self, size):
    if not isinstance(size, int):
        raise TypeError("size must be an integral type")
    if size < 0:
        raise ValueError("Size must be positive.")
    if size == 0:
        return b""

    if self.finished:
        data = self.buf.getvalue()
        ret, rest = data[:size], data[size:]
        self.buf = io.BytesIO()
        self.buf.write(rest)
        return ret

    data = self.unreader.read()
    while data:
        self.buf.write(data)
        if self.buf.tell() > size:
            break
        data = self.unreader.read()

    if not data:
        self.finished = True

    data = self.buf.getvalue()
    ret, rest = data[:size], data[size:]
    self.buf = io.BytesIO()
    self.buf.write(rest)
    return ret

def get_data(self, unreader, buf, stop=False):
    data = unreader.read()
    if not data:
        if stop:
            raise StopIteration()
        raise NoMoreData(buf.getvalue())
    buf.write(data)

def read_line(self, unreader, buf, limit=0):
    data = buf.getvalue()

    while True:
        idx = data.find(b"\r\n")
        if idx >= 0:
            # check if the request line is too large
            if idx > limit > 0:
                raise LimitRequestLine(idx, limit)
            break
        if len(data) - 2 > limit > 0:
            raise LimitRequestLine(len(data), limit)
        self.get_data(unreader, buf)
        data = buf.getvalue()

    return (data[:idx],  # request line,
            data[idx + 2:])  # residue in the buffer, skip \r\n

def read(self, size=None):
    if size is not None and not isinstance(size, int):
        raise TypeError("size parameter must be an int or long.")

    if size is not None:
        if size == 0:
            return b""
        if size < 0:
            size = None

    self.buf.seek(0, os.SEEK_END)

    if size is None and self.buf.tell():
        ret = self.buf.getvalue()
        self.buf = io.BytesIO()
        return ret
    if size is None:
        d = self.chunk()
        return d

    while self.buf.tell() < size:
        chunk = self.chunk()
        if not chunk:
            ret = self.buf.getvalue()
            self.buf = io.BytesIO()
            return ret
        self.buf.write(chunk)
    data = self.buf.getvalue()
    self.buf = io.BytesIO()
    self.buf.write(data[size:])
    return data[:size]

def unread(self, data):
    self.buf.seek(0, os.SEEK_END)
    self.buf.write(data)

def get_files(self):
    fnames = [
        COMPILED_EXT_RE.sub('py', module.__file__)
        for module in tuple(sys.modules.values())
        if getattr(module, '__file__', None)
    ]

    fnames.extend(self._extra_files)

    return fnames

def run(self):
    mtimes = {}
    while True:
        for filename in self.get_files():
            try:
                mtime = os.stat(filename).st_mtime
            except OSError:
                continue
            old_time = mtimes.get(filename)
            if old_time is None:
                mtimes[filename] = mtime
                continue
            elif mtime > old_time:
                if self._callback:
                    self._callback(filename)
        time.sleep(self._interval)

def add_extra_file(self, filename):
    dirname = os.path.dirname(filename)

    if dirname in self._dirs:
        return

    self._watcher.add_watch(dirname, mask=self.event_mask)
    self._dirs.add(dirname)

def get_dirs(self):
    fnames = [
        os.path.dirname(os.path.abspath(COMPILED_EXT_RE.sub('py', module.__file__)))
        for module in tuple(sys.modules.values())
        if getattr(module, '__file__', None)
    ]

    return set(fnames)

def run(self):
    self._dirs = self.get_dirs()

    for dirname in self._dirs:
        if os.path.isdir(dirname):
            self._watcher.add_watch(dirname, mask=self.event_mask)

    for event in self._watcher.event_gen():
        if event is None:
            continue

        filename = event[3]

        self._callback(filename)

