        config_uri,
        name=name,
        relative_to=os.getcwd(),
        global_conf=defaults,
    )

def run(self):
    if self.cfg.print_config:
        print(self.cfg)

    if self.cfg.print_config or self.cfg.check_config:
        try:
            self.load()
        except Exception:
            msg = "\nError while loading the application:\n"
            print(msg, file=sys.stderr)
            traceback.print_exc()
            sys.stderr.flush()
            sys.exit(1)
        sys.exit(0)

    if self.cfg.spew:
        debug.spew()

    if self.cfg.daemon:
        if os.environ.get('NOTIFY_SOCKET'):
            msg = "Warning: you shouldn't specify `daemon = True`" \
                  " when launching by systemd with `Type = notify`"
            print(msg, file=sys.stderr, flush=True)

        util.daemonize(self.cfg.enable_stdio_inheritance)

    # set python paths
    if self.cfg.pythonpath:
        paths = self.cfg.pythonpath.split(",")
        for path in paths:
            pythonpath = os.path.abspath(path)
            if pythonpath not in sys.path:
                sys.path.insert(0, pythonpath)

    super().run()

def serve(app, global_conf, **local_conf):
    """\
    A Paste Deployment server runner.

    Example configuration:

        [server:main]
        use = egg:gunicorn#main
        host = 127.0.0.1
        port = 5000
    """
    config_file = global_conf['__file__']
    gunicorn_config_file = local_conf.pop('config', None)

    host = local_conf.pop('host', '')
    port = local_conf.pop('port', '')
    if host and port:
        local_conf['bind'] = '%s:%s' % (host, port)
    elif host:
        local_conf['bind'] = host.split(',')

    class PasterServerApplication(WSGIApplication):
        def load_config(self):
            self.cfg.set("default_proc_name", config_file)

            if has_logging_config(config_file):
                self.cfg.set("logconfig", config_file)

            if gunicorn_config_file:
                self.load_config_from_file(gunicorn_config_file)
            else:
                default_gunicorn_config_file = get_default_config_file()
                if default_gunicorn_config_file is not None:
                    self.load_config_from_file(default_gunicorn_config_file)

            for k, v in local_conf.items():
                if v is not None:
                    self.cfg.set(k.lower(), v)

        def load(self):
            return app

    PasterServerApplication().run()

def init(self, parser, opts, args):
    self.app_uri = None

    if opts.paste:
        from .pasterapp import has_logging_config

        config_uri = os.path.abspath(opts.paste)
        config_file = config_uri.split('#')[0]

        if not os.path.exists(config_file):
            raise ConfigError("%r not found" % config_file)

        self.cfg.set("default_proc_name", config_file)
        self.app_uri = config_uri

        if has_logging_config(config_file):
            self.cfg.set("logconfig", config_file)

        return

    if len(args) > 0:
        self.cfg.set("default_proc_name", args[0])
        self.app_uri = args[0]

def has_logging_config(config_file):
    parser = configparser.ConfigParser()
    parser.read([config_file])
    return parser.has_section('loggers')

def write(self, data):
    for stream in self.streams:
        try:
            stream.write(data)
        except UnicodeError:
            stream.write(data.encode("UTF-8"))
        stream.flush()

def notify(self):
    super().notify()
    if self.ppid != os.getppid():
        self.log.info("Parent changed, shutting down: %s", self)
        sys.exit(0)

def run(self):
    servers = []
    ssl_args = {}

    if self.cfg.is_ssl:
        ssl_args = {"ssl_context": ssl_context(self.cfg)}

    for s in self.sockets:
        s.setblocking(1)
        pool = Pool(self.worker_connections)
        if self.server_class is not None:
            environ = base_environ(self.cfg)
            environ.update({
                "wsgi.multithread": True,
                "SERVER_SOFTWARE": VERSION,
            })
            server = self.server_class(
                s, application=self.wsgi, spawn=pool, log=self.log,
                handler_class=self.wsgi_handler, environ=environ,
                **ssl_args)
        else:
            hfun = partial(self.handle, s)
            server = StreamServer(s, handle=hfun, spawn=pool, **ssl_args)
            if self.cfg.workers > 1:
                server.max_accept = 1

        server.start()
        servers.append(server)

    while self.alive:
        self.notify()
        gevent.sleep(1.0)

    try:
        # Stop accepting requests
        for server in servers:
            if hasattr(server, 'close'):  # gevent 1.0
                server.close()
            if hasattr(server, 'kill'):  # gevent < 1.0
                server.kill()

        # Handle current requests until graceful_timeout
        ts = time.time()
        while time.time() - ts <= self.cfg.graceful_timeout:
            accepting = 0
            for server in servers:
                if server.pool.free_count() != server.pool.size:
                    accepting += 1

            # if no server is accepting a connection, we can exit
            if not accepting:
                return

            self.notify()
            gevent.sleep(1.0)

        # Force kill all active the handlers
        self.log.warning("Worker graceful timeout (pid:%s)", self.pid)
        for server in servers:
            server.stop(timeout=1)
    except Exception:
        pass

def proxy_environ(req):
    info = req.proxy_protocol_info

    if not info:
        return {}

    return {
        "PROXY_PROTOCOL": info["proxy_protocol"],
        "REMOTE_ADDR": info["client_addr"],
        "REMOTE_PORT": str(info["client_port"]),
        "PROXY_ADDR": info["proxy_addr"],
        "PROXY_PORT": str(info["proxy_port"]),
    }

def handle_error(self, req, client, addr, exc):
    request_start = datetime.now()
    addr = addr or ('', -1)  # unix socket case
    if isinstance(exc, (
        InvalidRequestLine, InvalidRequestMethod,
        InvalidHTTPVersion, InvalidHeader, InvalidHeaderName,
        LimitRequestLine, LimitRequestHeaders,
        InvalidProxyLine, ForbiddenProxyRequest,
        InvalidSchemeHeaders,
        SSLError,
    )):

        status_int = 400
        reason = "Bad Request"

        if isinstance(exc, InvalidRequestLine):
            mesg = "Invalid Request Line '%s'" % str(exc)
        elif isinstance(exc, InvalidRequestMethod):
            mesg = "Invalid Method '%s'" % str(exc)
        elif isinstance(exc, InvalidHTTPVersion):
            mesg = "Invalid HTTP Version '%s'" % str(exc)
        elif isinstance(exc, (InvalidHeaderName, InvalidHeader,)):
            mesg = "%s" % str(exc)
            if not req and hasattr(exc, "req"):
                req = exc.req  # for access log
        elif isinstance(exc, LimitRequestLine):
            mesg = "%s" % str(exc)
        elif isinstance(exc, LimitRequestHeaders):
            reason = "Request Header Fields Too Large"
            mesg = "Error parsing headers: '%s'" % str(exc)
            status_int = 431
        elif isinstance(exc, InvalidProxyLine):
            mesg = "'%s'" % str(exc)
        elif isinstance(exc, ForbiddenProxyRequest):
            reason = "Forbidden"
            mesg = "Request forbidden"
            status_int = 403
        elif isinstance(exc, InvalidSchemeHeaders):
            mesg = "%s" % str(exc)
        elif isinstance(exc, SSLError):
            reason = "Forbidden"
            mesg = "'%s'" % str(exc)
            status_int = 403

        msg = "Invalid request from ip={ip}: {error}"
        self.log.warning(msg.format(ip=addr[0], error=str(exc)))
    else:
        if hasattr(req, "uri"):
            self.log.exception("Error handling request %s", req.uri)
        status_int = 500
        reason = "Internal Server Error"
        mesg = ""

    if req is not None:
        request_time = datetime.now() - request_start
        environ = default_environ(req, client, self.cfg)
        environ['REMOTE_ADDR'] = addr[0]
        environ['REMOTE_PORT'] = str(addr[1])
        resp = Response(req, client, self.cfg)
        resp.status = "%s %s" % (status_int, reason)
        resp.response_length = len(mesg)
        self.log.access(resp, req, environ, request_time)

    try:
        util.write_error(client, status_int, reason, mesg)
    except Exception:
        self.log.debug("Failed to send error message.")

def should_close(self):
    if self.must_close or self.req.should_close():
        return True
    if self.response_length is not None or self.chunked:
        return False
    if self.req.method == 'HEAD':
        return False
    if self.status_code < 200 or self.status_code in (204, 304):
        return False
    return True

def default_headers(self):
    # set the connection header
    if self.upgrade:
        connection = "upgrade"
    elif self.should_close():
        connection = "close"
    else:
        connection = "keep-alive"

    headers = [
        "HTTP/%s.%s %s\r\n" % (self.req.version[0],
                               self.req.version[1], self.status),
        "Server: %s\r\n" % self.version,
        "Date: %s\r\n" % util.http_date(),
        "Connection: %s\r\n" % connection
    ]
    if self.chunked:
        headers.append("Transfer-Encoding: chunked\r\n")
    return headers

def write(self, arg):
    self.send_headers()
    if not isinstance(arg, bytes):
        raise TypeError('%r is not a byte' % arg)
    arglen = len(arg)
    tosend = arglen
    if self.response_length is not None:
        if self.sent >= self.response_length:
            # Never write more than self.response_length bytes
            return

        tosend = min(self.response_length - self.sent, tosend)
        if tosend < arglen:
            arg = arg[:tosend]

    # Sending an empty chunk signals the end of the
    # response and prematurely closes the response
    if self.chunked and tosend == 0:
        return

    self.sent += tosend
    util.write(self.sock, arg, self.chunked)

def close(self):
    if not self.headers_sent:
        self.send_headers()
    if self.chunked:
        util.write_chunk(self.sock, b"")

def is_chunked(self):
    # Only use chunked responses when the client is
    # speaking HTTP/1.1 or newer and there was
    # no Content-Length header set.
    if self.response_length is not None:
        return False
    elif self.req.version <= (1, 0):
        return False
    elif self.req.method == 'HEAD':
        # Responses to a HEAD request MUST NOT contain a response body.
        return False
    elif self.status_code in (204, 304):
        # Do not use chunked responses when the response is guaranteed to
        # not have a response body.
        return False
    return True

def sendfile(self, respiter):
    if self.cfg.is_ssl or not self.can_sendfile():
        return False

    if not util.has_fileno(respiter.filelike):
        return False

    fileno = respiter.filelike.fileno()
    try:
        offset = os.lseek(fileno, 0, os.SEEK_CUR)
        if self.response_length is None:
            filesize = os.fstat(fileno).st_size
            nbytes = filesize - offset
        else:
            nbytes = self.response_length
    except (OSError, io.UnsupportedOperation):
        return False

    self.send_headers()

    if self.is_chunked():
        chunk_size = "%X\r\n" % nbytes
        self.sock.sendall(chunk_size.encode('utf-8'))
    if nbytes > 0:
        self.sock.sendfile(respiter.filelike, offset=offset, count=nbytes)

    if self.is_chunked():
        self.sock.sendall(b"\r\n")

    os.lseek(fileno, offset, os.SEEK_SET)

    return True

def __init__(self, unreader, length):
    self.unreader = unreader
    self.length = length

def readlines(self, size=None):
    ret = []
    data = self.read()
    while data:
        pos = data.find(b"\n")
        if pos < 0:
            ret.append(data)
            data = b""
        else:
            line, data = data[:pos + 1], data[pos + 1:]
            ret.append(line)
    return ret

def __init__(self, host):
    self.host = host
    self.code = 403

def setup(cls):
    web = sys.modules.pop("tornado.web")
    old_clear = web.RequestHandler.clear

    def clear(self):
        old_clear(self)
        if "Gunicorn" not in self._headers["Server"]:
            self._headers["Server"] += " (Gunicorn/%s)" % gversion
    web.RequestHandler.clear = clear
    sys.modules["tornado.web"] = web

def clear(self):
    old_clear(self)
    if "Gunicorn" not in self._headers["Server"]:
        self._headers["Server"] += " (Gunicorn/%s)" % gversion

def wait(self, timeout):
    try:
        self.notify()
        ret = select.select(self.wait_fds, [], [], timeout)
        if ret[0]:
            if self.PIPE[0] in ret[0]:
                os.read(self.PIPE[0], 1)
            return ret[0]

    except select.error as e:
        if e.args[0] == errno.EINTR:
            return self.sockets
        if e.args[0] == errno.EBADF:
            if self.nr < 0:
                return self.sockets
            else:
                raise StopWaiting
        raise

def is_parent_alive(self):
    # If our parent changed then we shut down.
    if self.ppid != os.getppid():
        self.log.info("Parent changed, shutting down: %s", self)
        return False
    return True

def run_for_one(self, timeout):
    listener = self.sockets[0]
    while self.alive:
        self.notify()

        # Accept a connection. If we get an error telling us
        # that no connection is waiting we fall down to the
        # select which is where we'll wait for a bit for new
        # workers to come give us some love.
        try:
            self.accept(listener)
            # Keep processing clients until no one is waiting. This
            # prevents the need to select() for every client that we
            # process.
            continue

        except EnvironmentError as e:
            if e.errno not in (errno.EAGAIN, errno.ECONNABORTED,
                               errno.EWOULDBLOCK):
                raise

        if not self.is_parent_alive():
            return

        try:
            self.wait(timeout)
        except StopWaiting:
            return

def run_for_multiple(self, timeout):
    while self.alive:
        self.notify()

        try:
            ready = self.wait(timeout)
        except StopWaiting:
            return

        if ready is not None:
            for listener in ready:
                if listener == self.PIPE[0]:
                    continue

                try:
                    self.accept(listener)
                except EnvironmentError as e:
                    if e.errno not in (errno.EAGAIN, errno.ECONNABORTED,
                                       errno.EWOULDBLOCK):
                        raise

        if not self.is_parent_alive():
            return

def _eventlet_stop(client, server, conn):
    """
    Stop a greenlet handling a request and close its connection.

    This code is lifted from eventlet so as not to depend on undocumented
    functions in the library.
    """
    try:
        try:
            client.wait()
        finally:
            conn.close()
    except greenlet.GreenletExit:
        pass
    except Exception:
        greenthread.kill(server, *sys.exc_info())

def run(self):
    acceptors = []
    for sock in self.sockets:
        gsock = GreenSocket(sock)
        gsock.setblocking(1)
        hfun = partial(self.handle, gsock)
        acceptor = eventlet.spawn(_eventlet_serve, gsock, hfun,
                                  self.worker_connections)

        acceptors.append(acceptor)
        eventlet.sleep(0.0)

    while self.alive:
        self.notify()
        eventlet.sleep(1.0)

    self.notify()
    t = None
    try:
        with eventlet.Timeout(self.cfg.graceful_timeout) as t:
            for a in acceptors:
                a.kill(eventlet.StopServe())
            for a in acceptors:
                a.wait()
    except eventlet.Timeout as te:
        if te != t:
            raise
        for a in acceptors:
            a.kill()

def is_parent_alive(self):
    # If our parent changed then we shut down.
    if self.ppid != os.getppid():
        self.log.info("Parent changed, shutting down: %s", self)
        return False
    return True

def murder_keepalived(self):
    now = time.time()
    while True:
        with self._lock:
            try:
                # remove the connection from the queue
                conn = self._keep.popleft()
            except IndexError:
                break

        delta = conn.timeout - now
        if delta > 0:
            # add the connection back to the queue
            with self._lock:
                self._keep.appendleft(conn)
            break
        else:
            self.nr_conns -= 1
            # remove the socket from the poller
            with self._lock:
                try:
                    self.poller.unregister(conn.sock)
                except EnvironmentError as e:
                    if e.errno != errno.EBADF:
                        raise
                except KeyError:
                    # already removed by the system, continue
                    pass
                except ValueError:
                    # already removed by the system continue
                    pass

            # close the socket
            conn.close()

def set_timeout(self):
    # set the timeout
    self.timeout = time.time() + self.cfg.keepalive

def on_client_socket_readable(self, conn, client):
    with self._lock:
        # unregister the client from the poller
        self.poller.unregister(client)

        if conn.initialized:
            # remove the connection from keepalive
            try:
                self._keep.remove(conn)
            except ValueError:
                # race condition
                return

    # submit the connection to a worker
    self.enqueue_req(conn)

def _eventlet_socket_sendfile(self, file, offset=0, count=None):
    # Based on the implementation in gevent which in turn is slightly
    # modified from the standard library implementation.
    if self.gettimeout() == 0:
        raise ValueError("non-blocking sockets are not supported")
    if offset:
        file.seek(offset)
    blocksize = min(count, 8192) if count else 8192
    total_sent = 0
    # localize variable access to minimize overhead
    file_read = file.read
    sock_send = self.send
    try:
        while True:
            if count:
                blocksize = min(count - total_sent, blocksize)
                if blocksize <= 0:
                    break
            data = memoryview(file_read(blocksize))
            if not data:
                break  # EOF
            while True:
                try:
                    sent = sock_send(data)
                except BlockingIOError:
                    continue
                else:
                    total_sent += sent
                    if sent < len(data):
                        data = data[sent:]
                    else:
                        break
        return total_sent
    finally:
        if total_sent > 0 and hasattr(file, 'seek'):
            file.seek(offset + total_sent)

def init_process(self):
    self.patch()
    super().init_process()
